&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chercheur-(Oracle).html&quot; title=&quot;Chercheur&quot;&gt;Chercheur&lt;/a&gt; (RSE)&lt;/li&gt;
